const rows=registration.fixtures.map(fixture=>{
 const dir=realpathSync(join(fixtureRoot,fixture.id));
 const git=args=>{const result=spawnSync('git',['-C',dir,...args],{encoding:'utf8'});if(result.status!==0)throw Error(`git ${args[0]} ${result.stderr}`);return result.stdout.trim();};
 const head=git(['rev-parse','HEAD']); const tree=git(['rev-parse','HEAD^{tree}']);
 if(head!==fixture.parentCommit)throw Error(`parent mismatch ${fixture.id}`);
 const status=git(['status','--porcelain','--untracked-files=all']);if(status)throw Error(`unexpected parent change ${fixture.id}: ${status}`);
 const newPaths=fixture.truth.filter(item=>item.new).map(item=>{try{lstatSync(join(dir,item.path));throw Error(`NEW unexpectedly exists ${item.path}`);}catch(error){if(!['ENOENT','ENOTDIR'].includes(error.code))throw error;}return item.path;});
 const docs=join(dir,'docs');let docsLink=null;try{if(lstatSync(docs).isSymbolicLink())docsLink=readlinkSync(docs);}catch(error){if(error.code!=='ENOENT')throw error;}
 return {id:fixture.id,dir,head,tree,commonDir:realpathSync(git(['rev-parse','--path-format=absolute','--git-common-dir'])),workingTreeSha256:workingTreeSha256(dir),newAbsentPaths:newPaths,rootDocsLinkText:docsLink,parentStatus:status};
});
